import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Infra IA y LLM — El arquitecto del tier gratuito","description":"Puentes de API, routers de modelos, runtimes de agentes y autoalojamiento — infraestructura de IA que cuesta cero en correr.","frontmatter":{"title":"Infra IA y LLM — El arquitecto del tier gratuito","description":"Puentes de API, routers de modelos, runtimes de agentes y autoalojamiento — infraestructura de IA que cuesta cero en correr."},"headers":[],"relativePath":"es/skills/ai-llm/index.md","filePath":"es/skills/ai-llm/index.md"}`),a={name:`es/skills/ai-llm/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="infra-ia-y-llm-—-el-arquitecto-del-tier-gratuito" tabindex="-1">Infra IA y LLM — El arquitecto del tier gratuito <a class="header-anchor" href="#infra-ia-y-llm-—-el-arquitecto-del-tier-gratuito" aria-label="Permalink to “Infra IA y LLM — El arquitecto del tier gratuito”">​</a></h1><p>Cualquiera puede llamar a una API de pago. La ingeniería interesante es construir <strong>infraestructura sobre tiers gratuitos que se comporta como una de pago</strong> — y eso es exactamente lo que hacen mis proyectos de IA, por capas.</p><h2 id="las-capas" tabindex="-1">Las capas <a class="header-anchor" href="#las-capas" aria-label="Permalink to “Las capas”">​</a></h2><table tabindex="0"><thead><tr><th>Capa</th><th>Proyecto</th><th>Trabajo</th></tr></thead><tbody><tr><td>Acceso</td><td><a href="/Usf/es/projects/glm-free-api/">GLM Free API</a>, <a href="/Usf/es/projects/ghost-brain/">GhostBrain</a>, puentes qwen/deepseek</td><td>Convertir modelos web gratuitos en APIs reales compatibles con OpenAI/Anthropic.</td></tr><tr><td>Enrutamiento</td><td><a href="/Usf/es/projects/omnirouter/">OmniRouter</a></td><td>Balanceo, pesos, cuotas y failover entre proveedores.</td></tr><tr><td>Coordinación</td><td><a href="/Usf/es/projects/hermes-stack/">Hermes Stack</a></td><td>Runtime de agentes + automatizaciones + consola; autoalojado y gratis.</td></tr><tr><td>Consumo</td><td><a href="/Usf/es/agentic/overview/">OpenCode · Codex · Claude Code</a></td><td>Flota de agentes haciendo trabajo de ingeniería real sobre el stack.</td></tr></tbody></table><p>Las reglas de diseño son consistentes: nunca depender de un solo proveedor, nunca confiar en que un tier gratuito siga siendo gratuito, y tener siempre una salida de emergencia. Cuando un puente muere, el router lo banca; cuando una plataforma se vuelve hostil, aplica el <a href="/Usf/es/about/networking/">disciplinamiento de paneles</a> — migrar en minutos. El resultado es un stack de IA multi-modelo con factura mensual de exactamente cero.</p><p>En el ML en sí trabajo con TensorFlow, PyTorch, OpenCV y las herramientas de Hugging Face — con la profundidad suficiente para afinar, incrustar y evaluar, que suele ser todo lo que un producto realmente necesita.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};